	@Test
	void interruptedCoordinatorJoinsWorkersAndReturnsTerminalQueryCancellation() throws Exception {
		ProbeSource source = new ProbeSource(null, false);
		Scenario scenario = scenario(source);
		CountDownLatch kernelsStarted = new CountDownLatch(2);
		AtomicReference<Throwable> queryFailure = new AtomicReference<>();
		AtomicBoolean interruptedAtExit = new AtomicBoolean();
		ExecutorService workers = Executors.newFixedThreadPool(2);
		Thread query = new Thread(() -> {
			try {
				LmdbNativeParallelKernelAggregate.tryEvaluate(typeMatrixLowered(),
						new NativeLmdbQuerySource.NativeAdjacency[0], null, null,
						new TypeMatrixContext[] { typeMatrix() }, emptyDomains(), SlotPlan.singleton(), scenario.row,
						scenario.emitter, null, ignored -> new CancellationKernel(kernelsStarted), workers);
			} catch (Throwable problem) {
				queryFailure.set(problem);
			} finally {
				interruptedAtExit.set(Thread.currentThread().isInterrupted());
			}
		}, "native-aggregate-interrupted-coordinator-test");

		try {
			query.start();
			assertThat(kernelsStarted.await(10L, TimeUnit.SECONDS))
					.as("both workers must be active before interrupting the coordinator")
					.isTrue();
			query.interrupt();
			query.join(TimeUnit.SECONDS.toMillis(10L));
		} finally {
			scenario.emitter.requestCancellation();
			query.interrupt();
			query.join(TimeUnit.SECONDS.toMillis(10L));
			workers.shutdownNow();
			assertThat(workers.awaitTermination(10L, TimeUnit.SECONDS)).isTrue();
		}

		assertThat(query.isAlive()).isFalse();
		assertThat(interruptedAtExit).as("the coordinator must restore its interrupt status after draining workers")
				.isTrue();
		assertThat(queryFailure.get())
				.as("interrupting an aggregate coordinator is terminal query cancellation after every worker joins")
				.isInstanceOf(KernelQueryCancelledException.class);
		KernelQueryCancelledException cancellation = (KernelQueryCancelledException) queryFailure.get();
		assertThat(cancellation.origin())
				.as("the interrupt came from a non-owner coordinator thread")
				.isNull();
		assertThat(cancellation.observedBy(scenario.row.cancellation))
				.as("the scenario row token observed the unowned coordinator interrupt")
				.isTrue();
		assertThat(source.children).hasSize(2);
		for (ProbeSource child : source.children) {
			assertThat(child.workerFinished).isTrue();
			assertThat(child.closeCalls).hasValue(1);
			assertThat(child.closedWhileWorkerActive).isFalse();
		}
	}

