	@Test
	void capabilityDeclineAfterBothWorkersEngagedReturnsExactFallbackInsteadOfPeerCancellation() throws Exception {
		ProbeSource source = new ProbeSource(null, false);
		Scenario scenario = scenario(source);
		CountDownLatch workersEntered = new CountDownLatch(2);
		CountDownLatch declinePublished = new CountDownLatch(1);
		CountDownLatch workersFinished = new CountDownLatch(2);
		AtomicInteger workerNumber = new AtomicInteger();
		AtomicReference<List<BindingSet>> result = new AtomicReference<>();
		AtomicReference<Throwable> failure = new AtomicReference<>();
		ExecutorService workers = Executors.newFixedThreadPool(2);
		Thread query = new Thread(() -> {
			try {
				result.set(LmdbNativeParallelKernelAggregate.tryEvaluate(typeMatrixLowered(),
						new NativeLmdbQuerySource.NativeAdjacency[0], null, null,
						new TypeMatrixContext[] { typeMatrix() }, emptyDomains(), SlotPlan.singleton(), scenario.row,
						scenario.emitter, null,
						ignored -> new DeclineThenCancelKernel(workerNumber.getAndIncrement() == 0, workersEntered,
								declinePublished, workersFinished),
						workers));
			} catch (Throwable problem) {
				failure.set(problem);
			}
		}, "native-aggregate-capability-decline-test");

		try {
			query.start();
			assertThat(workersEntered.await(10L, TimeUnit.SECONDS))
					.as("both accepted workers must enter before one publishes its capability decline")
					.isTrue();
			query.join(TimeUnit.SECONDS.toMillis(10L));
		} finally {
			// Release every bounded wait on an assertion failure as well as on a normal completion, so this lifecycle
			// regression cannot leave an executor thread behind and hide the original failure.
			workersEntered.countDown();
			declinePublished.countDown();
			query.join(TimeUnit.SECONDS.toMillis(10L));
			workers.shutdownNow();
			assertThat(workers.awaitTermination(10L, TimeUnit.SECONDS)).isTrue();
		}

		assertThat(query.isAlive()).isFalse();
		assertThat(workersFinished.await(10L, TimeUnit.SECONDS))
				.as("the fallback decision must wait for both worker kernels to finish")
				.isTrue();
		assertThat(failure.get())
				.as("a cooperative sibling cancellation must not hide the capability decline fallback")
				.isNull();
		assertThat(result.get())
				.as("the direct seam represents an exact serial retry with null")
				.isNull();
		assertThat(source.children).hasSize(2);
		for (ProbeSource child : source.children) {
			assertThat(child.closeCalls).as("every worker snapshot must close after its kernel finishes").hasValue(1);
			assertThat(child.closedWhileWorkerActive)
					.as("fallback must join cooperative workers before closing snapshots")
					.isFalse();
		}
	}

