	private void runQueryCancellationAfterPeerStop(boolean repollAfterQuery) throws Exception {
		ProbeSource source = new ProbeSource(null, false);
		Scenario scenario = scenario(source);
		CountDownLatch workersEntered = new CountDownLatch(2);
		CountDownLatch declinePublished = new CountDownLatch(1);
		CountDownLatch peerStopped = new CountDownLatch(1);
		CountDownLatch workersFinished = new CountDownLatch(2);
		AtomicBoolean queryRequested = new AtomicBoolean();
		AtomicInteger workerNumber = new AtomicInteger();
		AtomicReference<List<BindingSet>> result = new AtomicReference<>();
		AtomicReference<Throwable> failure = new AtomicReference<>();
		ExecutorService workers = Executors.newFixedThreadPool(2);
		Thread query = new Thread(() -> {
			try {
				result.set(LmdbNativeParallelKernelAggregate.tryEvaluate(typeMatrixLowered(),
						new NativeLmdbQuerySource.NativeAdjacency[0], null, null,
						new TypeMatrixContext[] { typeMatrix() }, emptyDomains(), SlotPlan.singleton(), scenario.row,
						scenario.emitter, null,
						ignored -> new QueryCancellationAfterPeerKernel(workerNumber.getAndIncrement() == 0,
								workersEntered,
								declinePublished, peerStopped, queryRequested, workersFinished, repollAfterQuery),
						workers));
			} catch (Throwable problem) {
				failure.set(problem);
			}
		}, "native-aggregate-query-after-peer-stop-test");

		try {
			query.start();
			assertThat(workersEntered.await(10L, TimeUnit.SECONDS))
					.as("both accepted workers must enter before the capability result")
					.isTrue();
			assertThat(peerStopped.await(10L, TimeUnit.SECONDS))
					.as("the peer must stop before query cancellation is requested")
					.isTrue();
			assertThat(scenario.emitter.requestCancellation()).isTrue();
			queryRequested.set(true);
			query.join(TimeUnit.SECONDS.toMillis(10L));
		} finally {
			scenario.emitter.requestCancellation();
			queryRequested.set(true);
			workersEntered.countDown();
			declinePublished.countDown();
			peerStopped.countDown();
			query.join(TimeUnit.SECONDS.toMillis(10L));
			workers.shutdownNow();
			assertThat(workers.awaitTermination(10L, TimeUnit.SECONDS)).isTrue();
		}

		assertThat(query.isAlive()).isFalse();
		assertThat(workersFinished.await(10L, TimeUnit.SECONDS)).isTrue();
		assertThat(failure.get())
				.as("a terminal query cancellation must outrank the earlier peer stop")
				.satisfies(problem -> assertOwnedQueryCancellation(problem, scenario.row.cancellation));
		assertThat(result.get()).isNull();
	}

	@Test
	void ambientProbeDeadlineAfterPeerStopRemainsTerminal() throws Exception {
		ProbeSource source = new ProbeSource(null, false);
		Scenario scenario = scenario(source);
		CountDownLatch workersEntered = new CountDownLatch(2);
		CountDownLatch declinePublished = new CountDownLatch(1);
		CountDownLatch peerStopped = new CountDownLatch(1);
		CountDownLatch workersFinished = new CountDownLatch(2);
		AtomicBoolean probeRequested = new AtomicBoolean();
		AtomicInteger workerNumber = new AtomicInteger();
		AtomicReference<List<BindingSet>> result = new AtomicReference<>();
		AtomicReference<Throwable> failure = new AtomicReference<>();
		ExecutorService workers = Executors.newFixedThreadPool(2);
		LmdbNativeProbeDeadline deadline = LmdbNativeProbeDeadline.trippableOnly();
		Thread query = new Thread(() -> {
			try (LmdbNativeProbeDeadline.Scope ignored = LmdbNativeProbeDeadline.enter(deadline)) {
				try {
					result.set(LmdbNativeParallelKernelAggregate.tryEvaluate(typeMatrixLowered(),
							new NativeLmdbQuerySource.NativeAdjacency[0], null, null,
							new TypeMatrixContext[] { typeMatrix() }, emptyDomains(), SlotPlan.singleton(),
							scenario.row,
							scenario.emitter, null,
							ignoredKernel -> new ProbeDeadlineAfterPeerKernel(workerNumber.getAndIncrement() == 0,
									workersEntered, declinePublished, peerStopped, probeRequested, workersFinished),
							workers));
				} catch (Throwable problem) {
					failure.set(problem);
				}
			}
		}, "native-aggregate-probe-after-peer-stop-test");

		try {
			query.start();
			assertThat(workersEntered.await(10L, TimeUnit.SECONDS))
					.as("both accepted workers must enter before the capability result")
					.isTrue();
			assertThat(peerStopped.await(10L, TimeUnit.SECONDS))
					.as("the peer must stop before the ambient probe deadline is tripped")
					.isTrue();
			deadline.trip();
			probeRequested.set(true);
			query.join(TimeUnit.SECONDS.toMillis(10L));
		} finally {
			probeRequested.set(true);
			workersEntered.countDown();
			declinePublished.countDown();
			peerStopped.countDown();
			query.join(TimeUnit.SECONDS.toMillis(10L));
			workers.shutdownNow();
			assertThat(workers.awaitTermination(10L, TimeUnit.SECONDS)).isTrue();
		}

		assertThat(query.isAlive()).isFalse();
		assertThat(workersFinished.await(10L, TimeUnit.SECONDS)).isTrue();
		assertThat(failure.get())
				.as("an ambient probe deadline must remain a terminal probe signal after peer cancellation")
				.isSameAs(LmdbNativeProbeDeadlineExceeded.INSTANCE);
		assertThat(result.get()).isNull();
	}

	@Test
	void realWorkerFailureRetainsCleanupFailureIdentityThroughOuterAggregate() {
		IllegalStateException workerFailure = new IllegalStateException("worker probe failure");
		IllegalStateException cleanupFailure = new IllegalStateException("worker source close failure");
		ProbeSource source = new ProbeSource(workerFailure, false, false, cleanupFailure);
		Scenario scenario = scenario(source);

		Throwable problem = catchThrowable(() -> LmdbNativeKernelExecution.tryEvaluateAggregateParallel(
				scenario.plan, scenario.row, new int[0], AGGREGATES, scenario.emitter, null, null, true, true));

		assertThat(problem)
				.as("a real worker failure must remain the primary outer error")
				.isSameAs(workerFailure);
		assertThat(workerFailure.getSuppressed())
				.as("cleanup failure must remain attached to that occurrence")
				.contains(cleanupFailure);
	}

	@Test
	void unavailableParallelSourcesUseExactSerialFallbackAndReleaseReservation() {
		ProbeSource expectedSource = new ProbeSource(null, false);
		Scenario expectedScenario = scenario(expectedSource);
		List<BindingSet> expected = LmdbNativeKernelExecution.tryEvaluateAggregateSerial(expectedScenario.plan,
				expectedScenario.row, new int[0], AGGREGATES, expectedScenario.emitter, null, null, true, true);

		ProbeSource actualSource = new ProbeSource(null, true);
		Scenario actualScenario = scenario(actualSource);
		List<BindingSet> actual = LmdbNativeKernelExecution.tryEvaluateAggregate(actualScenario.plan,
				actualScenario.row,
				new int[0], AGGREGATES, actualScenario.emitter, null, null);

		assertThat(actual).containsExactlyElementsOf(expected);
		assertThat(actual).hasSize(1);
		Value count = actual.get(0).getValue("count");
		assertThat(count).isNotNull();
		assertThat(count.stringValue()).isEqualTo("8");
		assertThat(actualSource.parallelSourceCalls).hasValue(1);
		assertThat(actualSource.children).isEmpty();
		assertThat(actualSource.probeCloseCalls).hasValue(1);
		try (LmdbNativeParallelPipelines.TaskReservation reservation = LmdbNativeParallelPipelines
				.tryReserveTasks(false, 2)) {
			assertThat(reservation).as("an unavailable-source fallback must release its task reservation").isNotNull();
			assertThat(reservation.grantedWorkers()).isEqualTo(2);
		}
	}

	@Test
	void serialRowsPropagateTerminalProbeCancellation() throws Exception {
		Scenario scenario = scenario(new ProbeSource(null, false));
		SlotPlan plan = SlotPlan.union(scenario.plan, scenario.plan);
		assertRowAdmission(plan, scenario);
		LmdbNativeProbeDeadline deadline = LmdbNativeProbeDeadline.trippableOnly();
		try (LmdbNativeProbeDeadline.Scope ignored = LmdbNativeProbeDeadline.enter(deadline)) {
			deadline.trip();
			Throwable failure = catchThrowable(() -> openRows(plan, scenario));
			assertThat(failure).as("an expired private probe must not reopen an ordinary row fallback")
					.isSameAs(KernelCancelledException.INSTANCE);
		}
	}

	@Test
	void serialRowsPropagatePreBindAdjacencyIOExceptionAndCloseProbe() throws Exception {
		IOException sentinel = new IOException("pre-bind adjacency failure");
		ThrowingAdjacencyProbeSource source = new ThrowingAdjacencyProbeSource(sentinel);
		Scenario scenario = scenario(source);
		SlotPlan plan = SlotPlan.union(scenario.plan, scenario.plan);
		try {
			assertRowAdmission(plan, scenario);
			((ProbeSource) source).probeCloseCalls.set(0);
			source.throwOnAdjacency = true;
			Throwable failure = catchThrowable(() -> openRows(plan, scenario));
			assertThat(failure).as("pre-bind storage I/O failures must propagate unchanged").isSameAs(sentinel);
			assertThat(((ProbeSource) source).probeCloseCalls)
					.as("the rejected pre-bind probe must still be closed")
					.hasValue(1);
		} finally {
			scenario.emitter.close();
		}
	}

