	/** Used in a bounded child JVM because a broken startup barrier cannot be cancelled by the query owner. */
	void exerciseWorkerActivationFailure(boolean matrix) {
		ProbeSource source = new ProbeSource(null, false);
		Scenario scenario = scenario(source);
		RuntimeException injected = new IllegalStateException("native worker activation rejected");
		AtomicBoolean rejectFirst = new AtomicBoolean(true);
		AtomicInteger activated = new AtomicInteger();
		Throwable failure;
		try (var scope = QueryExecutionContext.activateReplaySafepoint(() -> {
		}, () -> () -> {
			System.out.println("WORKER_ACTIVATED " + activated.incrementAndGet());
			if (rejectFirst.compareAndSet(true, false)) {
				throw injected;
			}
			return () -> {
			};
		})) {
			failure = catchThrowable(() -> {
				if (matrix) {
					LmdbNativeParallelKernelAggregate.tryEvaluate(typeMatrixLowered(),
							new NativeLmdbQuerySource.NativeAdjacency[0], null, null,
							new TypeMatrixContext[] { typeMatrix() }, emptyDomains(), SlotPlan.singleton(),
							scenario.row,
							scenario.emitter, null, ignored -> new CancellationKernel(new CountDownLatch(0)));
				} else {
					LmdbNativeKernelExecution.tryEvaluateAggregateParallel(scenario.plan, scenario.row,
							new int[0], AGGREGATES, scenario.emitter, null, null, true, true);
				}
			});
		}
		assertThat(activated.get()).as("both admitted kernel workers must activate").isEqualTo(2);
		assertThat(LmdbNativeWorkerLifecycleTest.hasCause(failure, injected)).isTrue();
		assertThat(source.children).hasSize(2);
		for (ProbeSource child : source.children) {
			assertThat(child.closeCalls).hasValue(1);
		}
	}

	private Scenario scenario(ProbeSource source) {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("subject", 0, "object", 1), null);
		layout.freeze(List.of("subject", "object"));
		PatternPlan plan = aggregatePlan();
		NativeGroupIteration emitter = new NativeGroupIteration(source, plan, layout, new int[0], AGGREGATES,
				false, EmptyBindingSet.getInstance(), null, null, false, null);
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance(), (TupleExpr) null,
				emitter.cancellation);
		assertThat(emitter.initialize(row)).isTrue();
		return new Scenario(plan, row, emitter);
	}

	private static PatternPlan aggregatePlan() {
		return new PatternPlan(Term.slot(0), Term.constant(PREDICATE), Term.slot(1), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, ROOTS);
	}

	private static LmdbNativeKernelLowering.Lowered typeMatrixLowered() {
		TypeMatrixAggregate terminal = new TypeMatrixAggregate(0, false, 0, 1);
		Kernel kernel = new Kernel(0, List.of(), terminal);
		LmdbNativeKernelBindings bindings = new LmdbNativeKernelBindings(
				new LmdbNativeKernelBindings.AdjacencyRequest[0], new long[0], new int[0],
				new LmdbNativeKernelBindings.DomainRequest[0], new LmdbNativeKernelBindings.FilterHook[0], new int[0],
				List.of())
						.withTypeMatrixRequests(new LmdbNativeKernelBindings.TypeMatrixRequest[] {
								new LmdbNativeKernelBindings.TypeMatrixRequest(1L, 2L, new MaskedFilter[0], -1) });
		return new LmdbNativeKernelLowering.Lowered(kernel, bindings);
	}

	private static TypeMatrixContext typeMatrix() {
		return new TypeMatrixContext(ProbeSource.ADJACENCY, null, null, new NativeLmdbQuerySource.NativeAdjacency[0],
				new long[0]);
	}

